        return Task.FromResult(count);
    }

    /// <summary>
    /// Called by the polling component to store the latest count and notify all subscribers.
    /// </summary>
    public void UpdateLatestCount(int count)
    {
        LatestLowStockCount = count;
        OnChange?.Invoke();
    }
}

