@page "/dashboard"
@inject WarehouseState Warehouse
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard — @Warehouse.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-4">@Warehouse.CurrentWarehouseName</p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            @if (AlertService.LatestLowStockCount > 0)
            {
                <span class="text-danger fs-3 fw-bold">@AlertService.LatestLowStockCount</span>
                <span class="text-muted ms-2">items below minimum level</span>
            }
            else
            {
                <span class="text-success fs-3 fw-bold">0</span>
                <span class="text-muted ms-2">all stock levels healthy</span>
            }
        </p>
        <small class="text-muted">Polling every 10 seconds</small>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        // Re-render when warehouse changes so the heading updates.
        _warehouseHandler = () => InvokeAsync(() =>
        {
            StateHasChanged();
            // Immediately re-poll when the warehouse changes.
            _ = PollOnceAsync();
        });
        Warehouse.OnChange += _warehouseHandler;

        // Re-render when alert data arrives (from our own poll or any future source).
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _alertHandler;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Immediate first poll.
        await PollOnceAsync();

        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await PollOnceAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose.
        }
    }

    private async Task PollOnceAsync()
    {
        var count = await AlertService.GetLowStockCountAsync(Warehouse.CurrentWarehouseId);
        // Push the result through the shared service so ALL subscribers update.
        AlertService.UpdateLatestCount(count);
    }

    public void Dispose()
    {
        Warehouse.OnChange -= _warehouseHandler;
        AlertService.OnChange -= _alertHandler;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

